// 所有未来/历史判断交叉核实例号、Common事实序与业务tick；当前余额不能证明过去已清。
#include "task_shop_order_sources.hpp"
#include <charconv>
#include <map>
namespace hanmo::resident {namespace {
std::optional<Integer> serial(const StableId& id,const StableId& prefix,Integer next){const auto head=prefix+":";if(id.rfind(head,0)!=0)return {};auto text=id.substr(head.size());Integer n=0;auto parsed=std::from_chars(text.data(),text.data()+text.size(),n);if(parsed.ec!=std::errc{}||parsed.ptr!=text.data()+text.size()||n<=0||n>=next||std::to_string(n)!=text)return {};return n;}
struct Boundary {Integer cutoff=0,tick=0;StableId fact;};
Outcome<Boundary> boundary_at(const CommonStore& c,const StableId& fact,Integer tick,const StableId& prefix,const StableId& kind,const StableId& domain){if(fact.empty())return {true,{c.state().next_instance_id,c.tick(),{}},{}};const auto n=serial(fact,prefix,c.state().next_instance_id);const auto* header=c.state().facts.find(fact);if(!n||!header||header->id!=fact||header->kind!=kind||header->domain!=domain||tick<0||tick>c.tick())return {false,{},common_failure("TaskShopOrderHistoryBoundaryUnavailable",fact).error};return {true,{*n,tick,fact},{}};}
Outcome<bool> before(const CommonStore& c,const Boundary& bound,const StableId& fact,const StableId& prefix,Integer tick){const auto n=serial(fact,prefix,c.state().next_instance_id);const auto& facts=c.state().facts.order();const auto at=std::find(facts.begin(),facts.end(),fact),end=bound.fact.empty()?facts.end():std::find(facts.begin(),facts.end(),bound.fact);if(!n||at==facts.end()||(!bound.fact.empty()&&end==facts.end())||((*n<bound.cutoff)!=(at<end))||(*n<bound.cutoff?tick>bound.tick:tick<bound.tick))return {false,{},common_failure("TaskShopOrderHistoryOrderMismatch",fact).error};return {true,*n<bound.cutoff,{}};}
const TaskShopOrderSettlement* settled(const TaskShopOrderState& state,const StableId& task){for(const auto& row:state.settlements.rows())if(row.second.task_id==task)return &row.second;return nullptr;}
Outcome<bool> finished(const CommonStore& c,const TaskShopOrderState& state,const TaskShopOrderBinding& binding,const Boundary& bound){const auto* receipt=settled(state,binding.task_id);if(!receipt)return {true,false,{}};auto earlier=before(c,bound,receipt->fact_id,task_shop_order_settled_kind,receipt->tick);if(!earlier.ok||!earlier.value)return earlier;const auto sequence=serial(receipt->settlement_id,"settlement",c.state().next_instance_id);if(!sequence||*sequence>=bound.cutoff)return {false,{},common_failure("TaskShopOrderSettlementBoundaryMismatch",binding.task_id).error};if(receipt->termination==task_shop_order_estate_termination){if(!state.estate_cancellations)return {false,{},common_failure("TaskShopOrderEstateSourceRequired",binding.task_id).error};const TaskShopOrderEstateCancellation* executor=nullptr;for(const auto& row:state.estate_cancellations->cancellations.rows())if(row.second.settlement_fact_id==receipt->fact_id)executor=&row.second;if(!executor)return {false,{},common_failure("TaskShopOrderEstateSourceRequired",binding.task_id).error};auto actual=before(c,bound,executor->fact_id,task_shop_order_estate_cancelled_kind,executor->tick);if(!actual.ok||!actual.value)return actual;}return {true,true,{}};}
}
Outcome<std::vector<StableId>> read_task_shop_order_actor_pending(const CommonStore& c,const TaskState& tasks,const TaskShopOrderState& state,const StableId& actor){auto valid=validate_task_shop_order_ledger(c,tasks,state);if(!valid.ok)return {false,{},valid.error};std::vector<StableId> out;for(const auto& row:state.bindings.rows()){const auto& b=row.second;if(b.terms.proprietor_actor_id!=actor&&b.terms.original_client.id!=actor)continue;if(!settled(state,b.task_id))out.push_back(b.task_id);}return {true,std::move(out),{}};}
Status validate_task_shop_order_actor_history(const CommonStore& c,const TaskState& tasks,const TaskShopOrderState& state,const StableId& actor,const StableId& fact,Integer tick){auto valid=validate_task_shop_order_ledger(c,tasks,state);if(!valid.ok)return valid;auto bound=boundary_at(c,fact,tick,"family_inheritance","family_inheritance_settled","family_inheritance");if(!bound.ok)return {false,{},bound.error};for(const auto& row:state.bindings.rows()){const auto& b=row.second;if(b.terms.proprietor_actor_id!=actor&&b.terms.original_client.id!=actor)continue;auto accepted=before(c,bound.value,b.fact_id,task_shop_order_acceptance_prefix,b.terms.accepted_tick);if(!accepted.ok)return {false,{},accepted.error};if(!accepted.value)continue;auto result=finished(c,state,b,bound.value);if(!result.ok)return {false,{},result.error};if(!result.value)return common_failure("InheritanceResponsibilityHistoryUnavailable",b.task_id);}return common_success();}
Outcome<std::vector<StableId>> task_shop_order_journal_lines(const CommonStore& c,const TaskState& tasks,const TaskShopOrderState& state,const TaskCatalog& catalog,const StableId& actor,const StableId& id){auto valid=validate_task_shop_order_ledger(c,tasks,state);if(!valid.ok)return {false,{},valid.error};const auto at=state.by_task.find(id);const auto* b=at==state.by_task.end()?nullptr:state.bindings.find(at->second);if(!b||b->terms.proprietor_actor_id!=actor)return {false,{},common_failure("TaskShopOrderNotKnown",id).error};const auto* item=catalog.presentation_names.find("items/"+b->terms.item_id);std::vector<StableId> lines{"本人店单 · "+id,(item?*item:b->terms.item_id)+" × "+std::to_string(b->terms.quantity)+"；原客户总价 "+std::to_string(b->terms.contract_price)+" 钱。"};const auto* receipt=settled(state,id);if(!receipt)lines.push_back("尚未交付，客户价款仍为预约。请从本人店单页当面交货或取消；原截止半日 "+std::to_string(b->terms.deadline_tick)+"。");else if(receipt->outcome=="delivered")lines.push_back("已实际交货并将 "+std::to_string(receipt->paid_price)+" 钱收进原店钱包。");else lines.push_back("未交订单已取消，原预约已释放，没有现金退款。");return {true,std::move(lines),{}};}
Outcome<TaskFulfilledClients> read_task_shop_order_fulfilled_clients(const CommonStore& c,const TaskState& tasks,const TaskShopOrderState& state,const StableId& actor,const TaskFulfilledClientBoundary* cutoff,const DynamicStepInput* phase){auto valid=validate_task_shop_order_ledger(c,tasks,state,phase);if(!valid.ok)return {false,{},valid.error};auto bound=boundary_at(c,cutoff?cutoff->opening_fact_id:StableId{},cutoff?cutoff->opening_tick:-1,"private_shop","private_shop_opened","private_shops");if(!bound.ok)return {false,{},bound.error};// 全账允许同一严格phase已完成来源；历史开店的原tick和两种序界不扩。
    if(!cutoff&&phase)bound.value.tick=phase->to_tick;TaskFulfilledClients result{c.state().identity,actor,{}};std::map<std::pair<int,StableId>,TaskFulfilledClientSource> clients;
    for(const auto& row:state.bindings.rows()){const auto& b=row.second;if(b.terms.proprietor_actor_id!=actor)continue;auto accepted=before(c,bound.value,b.fact_id,task_shop_order_acceptance_prefix,b.terms.accepted_tick);if(!accepted.ok)return {false,{},accepted.error};if(!accepted.value)continue;auto complete=finished(c,state,b,bound.value);if(!complete.ok)return {false,{},complete.error};if(!complete.value)continue;const auto* receipt=settled(state,b.task_id);if(receipt->outcome!="delivered")continue;TaskFulfilledClientSource source;source.original_client=b.terms.original_client;source.delivery_beneficiary={SubjectKind::actor,b.terms.original_client.id};source.task_id=b.task_id;source.settlement_id=receipt->settlement_id;source.template_id="shop_order";source.payment_fact_id=receipt->fact_id;source.completed_tick=receipt->tick;source.objective_fact_ids={receipt->fact_id};const auto key=std::make_pair(static_cast<int>(source.original_client.kind),source.original_client.id);auto found=clients.find(key);if(found==clients.end()||*serial(source.settlement_id,"settlement",c.state().next_instance_id)<*serial(found->second.settlement_id,"settlement",c.state().next_instance_id))clients[key]=std::move(source);}
    for(auto& row:clients)result.clients.push_back(std::move(row.second));return {true,std::move(result),{}};
}
bool task_shop_order_reservation_exists(const TaskState& tasks,const TaskShopOrderState& state,const StableId& id){for(const auto& row:state.bindings.rows())if(row.second.reservation_id==id){const auto* task=tasks.tasks.find(row.second.task_id);return task&&task->status=="active"&&task->id==row.second.task_id&&task->assignee==row.second.terms.proprietor_actor_id&&task->settlement_id.empty();}return false;}
}
